f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>{html_escape(self.title)} - {html_escape(report_date)}</title>
  <style>
    :root {{
      color-scheme: dark;
    }}
    body {{
      margin: 0;
      background: {CSS_PALETTE['bg_primary']};
      color: {CSS_PALETTE['text_primary']};
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
      line-height: 1.5;
    }}
    .page {{
      max-width: 1280px;
      margin: 0 auto;
      padding: 28px 20px 48px;
    }}
    .hero {{
      border: 1px solid {CSS_PALETTE['border']};
      background: linear-gradient(135deg, {CSS_PALETTE['bg_secondary']} 0%, {CSS_PALETTE['bg_card']} 100%);
      padding: 20px 22px;
      margin-bottom: 18px;
      border-radius: 14px;
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.18);
    }}
    .eyebrow {{
      color: {CSS_PALETTE['blue']};
      text-transform: uppercase;
      letter-spacing: 0.12em;
      font-size: 11px;
      margin-bottom: 8px;
    }}
    h1 {{
      margin: 0;
      font-size: 28px;
      line-height: 1.2;
    }}
    .subtitle {{
      margin-top: 8px;
      color: {CSS_PALETTE['text_secondary']};
    }}
    .meta {{
      margin-top: 12px;
      color: {CSS_PALETTE['text_secondary']};
      font-size: 12px;
    }}
    .section-card {{
      border: 1px solid {CSS_PALETTE['border']};
      background: {CSS_PALETTE['bg_card']};
      border-radius: 14px;
      padding: 16px 18px 18px;
      margin: 0 0 16px;
    }}
    .section-header {{
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      margin-bottom: 8px;
    }}
    h2 {{
      margin: 0;
      font-size: 16px;
      letter-spacing: 0.03em;
      text-transform: uppercase;
    }}
    .section-summary {{
      margin: 0 0 12px;
      color: {CSS_PALETTE['text_secondary']};
    }}
    .badge {{
      display: inline-flex;
      align-items: center;
      padding: 3px 10px;
      border-radius: 999px;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      border: 1px solid transparent;
      white-space: nowrap;
    }}
    .badge-ok {{
      color: {CSS_PALETTE['green']};
      background: rgba(46, 160, 67, 0.12);
      border-color: rgba(46, 160, 67, 0.45);
    }}
    .badge-warn {{
      color: {CSS_PALETTE['amber']};
      background: rgba(210, 153, 34, 0.12);
      border-color: rgba(210, 153, 34, 0.45);
    }}
    .badge-critical {{
      color: {CSS_PALETTE['red']};
      background: rgba(248, 81, 73, 0.12);
      border-color: rgba(248, 81, 73, 0.45);
    }}
    .badge-muted {{
      color: {CSS_PALETTE['text_secondary']};
      background: rgba(139, 148, 158, 0.1);
      border-color: rgba(139, 148, 158, 0.35);
    }}
    .metric-grid {{
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
      gap: 10px;
      margin-bottom: 14px;
    }}
    .metric-card {{
      padding: 10px 12px;
      border-radius: 10px;
      background: {CSS_PALETTE['bg_secondary']};
      border: 1px solid {CSS_PALETTE['border']};
    }}
    .metric-label {{
      color: {CSS_PALETTE['text_secondary']};
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 4px;
    }}
    .metric-value {{
      font-size: 20px;
      font-weight: 700;
    }}
    .metric-meta, .kv-extra, .section-note {{
      color: {CSS_PALETTE['text_secondary']};
      font-size: 12px;
    }}
    .kv-grid {{
      display: grid;
      gap: 8px;
    }}
    .kv-row {{
      display: flex;
      justify-content: space-between;
      gap: 16px;
      padding: 8px 0;
      border-bottom: 1px solid rgba(48, 54, 61, 0.6);
    }}
    .kv-row:last-child {{
      border-bottom: 0;
    }}
    .kv-label {{
      color: {CSS_PALETTE['text_secondary']};
    }}
    .kv-value {{
      text-align: right;
      font-weight: 600;
    }}
    .table-wrap {{
      overflow-x: auto;
      border: 1px solid {CSS_PALETTE['border']};
      border-radius: 10px;
      background: {CSS_PALETTE['bg_secondary']};
    }}
    table {{
      width: 100%;
      border-collapse: collapse;
      font-size: 12px;
    }}
    th, td {{
      padding: 9px 10px;
      border-bottom: 1px solid rgba(48, 54, 61, 0.65);
      text-align: left;
      vertical-align: top;
    }}
    th {{
      color: {CSS_PALETTE['text_secondary']};
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      background: rgba(13, 17, 23, 0.3);
    }}
    tr:last-child td {{
      border-bottom: 0;
    }}
    .chart-block {{
      margin-top: 12px;
      padding: 12px;
      border: 1px solid {CSS_PALETTE['border']};
      border-radius: 10px;
      background: {CSS_PALETTE['bg_secondary']};
    }}
    .chart-title {{
      margin-bottom: 8px;
      color: {CSS_PALETTE['text_secondary']};
      font-size: 12px;
      text-transform: uppercase;
      letter-spacing: 0.05em;
    }}
    .svg-chart {{
      display: block;
      max-width: 100%;
      overflow: visible;
    }}
    .bullet-list {{
      margin: 0;
      padding-left: 18px;
    }}
    .bullet-list li {{
      margin: 5px 0;
    }}
    .split-grid {{
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 12px;
    }}
    .warning-row {{
      padding-top: 8px;
      color: {CSS_PALETTE['amber']};
      font-size: 12px;
    }}
    .unavailable-block {{
      padding: 10px 12px;
      border-radius: 10px;
      border: 1px dashed {CSS_PALETTE['gray']};
      color: {CSS_PALETTE['text_secondary']};
      background: rgba(110, 118, 129, 0.08);
    }}
    p {{
      margin: 8px 0;
    }}
  </style>
</head>
<body>
  <main class="page">
    <header class="hero">
      <div class="eyebrow">{html_escape(report_type)}</div>
      <h1>{html_escape(self.title)}</h1>
      {subtitle_html}
      <div class="meta">Report date: {html_escape(report_date)} | Generated: {html_escape(generated_at.isoformat())}</div>
    </header>
    {sections_html}
  </main>
</body>
</html>"""

